1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>arXiv Public Link Styles — Component Reference</title>
7	<link rel="stylesheet" href="design-system.css">
8	<style>
9	  /* Page chrome — not part of the component system; only here to host
10	     the reference itself. Mirrors button-styles.html. */
11	  *, *::before, *::after { box-sizing: border-box; }
12	  body {
13	    font-family: var(--arxiv-font-sans);
14	    color: var(--arxiv-ink);
15	    background: var(--arxiv-warm-wash);
16	    margin: 0;
17	    padding: 0;
18	    font-size: 14px;
19	    line-height: 1.55;
20	  }
21	  .page { max-width: 980px; margin: 0 auto; padding: 48px 28px 80px; }
22	
23	  .page-header { margin-bottom: 40px; padding-bottom: 18px; border-bottom: 3px solid var(--arxiv-open-blue); }
24	  .page-header h1 { font-size: 24px; font-weight: 700; margin: 0 0 6px; }
25	  .page-header p { margin: 0; color: var(--arxiv-grey); font-size: 13px; max-width: 680px; }
26	
27	  .back-link {
28	    display: inline-block; margin-bottom: 20px;
29	    font-size: 13px;
30	    color: var(--arxiv-link-blue);
31	    text-decoration: none;
32	  }
33	  .back-link:hover { text-decoration: underline; text-underline-offset: 2px; color: var(--arxiv-link-hover); }
34	
35	  .section { margin-bottom: 44px; }
36	  .section-title { font-size: 18px; font-weight: 600; margin: 0 0 6px; }
37	  .section-desc { margin: 0 0 18px; color: var(--arxiv-grey); font-size: 13px; max-width: 680px; line-height: 1.55; }
38	
39	  /* Side-by-side light/dark preview panels — same pattern as
40	     alert-styles.html in the working mockups. The dark panel scopes
41	     the dark-mode token overrides locally so both modes are visible
42	     simultaneously without depending on the user's OS theme. */
43	  .preview-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; }
44	  @media (max-width: 760px) { .preview-grid { grid-template-columns: 1fr; } }
45	  .preview-panel { padding: 22px 22px 24px; border-radius: 8px; border: 1px solid #e0dbd7; }
46	  .preview-panel.light { background: #ffffff; color: var(--arxiv-ink); }
47	  .preview-panel.dark {
48	    background: #1c1a17;
49	    border-color: #33302c;
50	    color: #e0dbd7;
51	    /* Mirror the @media (prefers-color-scheme: dark) token overrides
52	       from design-system.css so the dark panel renders correctly
53	       regardless of the viewer's OS theme. */
54	    --arxiv-link-blue:    #64b5f6;
55	    --arxiv-link-hover:   #90caf9;
56	    --arxiv-link-visited: #c084e0;
57	  }
58	  .preview-panel > h3 {
59	    font-family: var(--arxiv-font-condensed);
60	    font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em;
61	    color: var(--arxiv-grey); margin: 0 0 16px; font-weight: 600;
62	  }
63	  .preview-panel.dark > h3 { color: #9e9891; }
64	
65	  /* State strip — one row of label + sample per state. */
66	  .state-row { display: flex; gap: 24px; flex-wrap: wrap; margin-bottom: 8px; }
67	  .state-cell { display: flex; flex-direction: column; gap: 6px; min-width: 110px; }
68	  .state-label {
69	    font-family: var(--arxiv-font-condensed);
70	    font-weight: 600; font-size: 10px;
71	    color: var(--arxiv-grey);
72	    text-transform: uppercase; letter-spacing: 0.06em;
73	  }
74	  .preview-panel.dark .state-label { color: #9e9891; }
75	
76	  /* Forced-state classes so we can demo :hover and :visited without
77	     waiting for the user to actually hover or visit. These are
78	     scaffolding for the demo only — they would never appear in
79	     production code. */
80	  .ds-link.sim-hover    { color: var(--arxiv-link-hover); }
81	  .ds-link.sim-visited  { color: var(--arxiv-link-visited); }
82	
83	  .ratio {
84	    display: block; margin-top: 6px;
85	    font-family: var(--arxiv-font-mono); font-size: 11px;
86	    color: var(--arxiv-grey);
87	  }
88	  .preview-panel.dark .ratio { color: #9e9891; }
89	
90	  /* In-context paragraph */
91	  .body-text {
92	    font-size: 14px; line-height: 1.7;
93	    margin: 16px 0 0;
94	  }
95	  .body-text + .body-text { margin-top: 12px; }
96	  .body-meta {
97	    margin: 12px 0 0;
98	    font-size: 12.5px;
99	    color: var(--arxiv-grey);
100	  }
101	  .preview-panel.dark .body-meta { color: #9e9891; }
102	
103	  /* Callout */
104	  .callout {
105	    font-size: 13px; line-height: 1.6; margin-top: 18px; padding: 12px 16px;
106	    background: #ffffff; border: 1px solid #e0dbd7;
107	    border-left: 4px solid var(--arxiv-link-blue);
108	    border-radius: 0 4px 4px 0;
109	  }
110	  .callout + .callout { margin-top: 10px; }
111	  .callout strong { color: var(--arxiv-ink); }
112	  .note-alert { margin-top: 18px; }
113	
114	  code {
115	    font-family: var(--arxiv-font-mono); font-size: 12px;
116	    background: var(--arxiv-card-grey); padding: 2px 5px; border-radius: 3px;
117	  }
118	  .preview-panel.dark code { background: #2a2724; color: #e0dbd7; }
119	
120	  /* Token reference table */
121	  .token-table {
122	    width: 100%; border-collapse: collapse; background: #fff;
123	    border: 1px solid #e0dbd7; border-radius: 8px; overflow: hidden; font-size: 13px;
124	  }
