/* ═══════════════════════════════════════════════════════════════════════
   ARTIFACT LINKS CARD  (.ds-artifact-links and parts)
   ───────────────────────────────────────────────────────────────────────
   Browsable card listing a paper's external research artifacts (datasets,
   code repositories, supplementary material) on the public abstract page.
   Reads as supplementary material, not as a primary call to action.

   Parts:
     .ds-artifact-links          Card container (<section> recommended).
     .ds-artifact-links-title    Consumer heading (any h2–h6 level).
     .ds-artifact-links-list     <ul> of artifact rows.
     .ds-artifact-links-row      <a> — the full interactive row.
       .ds-artifact-links-label  Artifact label ("Training data").
       .ds-artifact-links-dest   Destination name ("Zenodo", "GitHub").
       .ds-artifact-links-ext    Off-site arrow SVG (aria-hidden="true").
     .ds-artifact-links-more     <details> overflow block — used when
                                 there are more than 8 artifacts. Its
                                 <summary> carries the count of hidden
                                 items ("4 more artifacts"). The inner
                                 <ul> reuses .ds-artifact-links-list;
                                 no additional CSS class needed.

   Overflow rule: show the first 8 artifacts in .ds-artifact-links-list
   without any disclosure. At 9 or more, the consumer wraps the excess
   items in .ds-artifact-links-more (a <details> element). The +/−
   glyph on the summary follows the .ds-acc convention. No transition
   on the disclosure itself — nothing for prefers-reduced-motion to
   disable on a pure-CSS open/close.

   External links: every .ds-artifact-links-row is a target="_blank"
   link. Include rel="noopener noreferrer" and per-row:
   <span class="is-sr-only">(opens in new tab)</span>.

   ARIA: wrap in <section aria-labelledby="[heading-id]"> so assistive
   technology announces the card name before traversing the list.

   Hover: Active Wash (--arxiv-active-bg) — same token as
   .ds-toc-dropdown-link hover, keeping all arXiv-layer interactive
   rows visually unified.
   Focus: 3px ring at 2px inset (same as .ds-acc summary treatment).
   Visited: suppressed (color stays --arxiv-ink). These are navigational
   links, not inline body text; per-visit history is not useful here.

   Example (minimal):
     <section class="ds-artifact-links" aria-labelledby="al-h">
       <h2 class="ds-artifact-links-title" id="al-h">Data &amp; code</h2>
       <ul class="ds-artifact-links-list">
         <li>
           <a class="ds-artifact-links-row"
              href="https://zenodo.org/record/1234567"
              target="_blank" rel="noopener noreferrer">
             <span class="ds-artifact-links-label">Training data</span>
             <span class="ds-artifact-links-dest">Zenodo</span>
             <svg class="ds-artifact-links-ext" aria-hidden="true"
                  viewBox="0 0 12 12" fill="none"
                  stroke="currentColor" stroke-width="1.75"
                  stroke-linecap="round" stroke-linejoin="round">
               <path d="M2 10L10 2M5 2H10V7"/>
             </svg>
             <span class="is-sr-only">(opens in new tab)</span>
           </a>
         </li>
       </ul>
     </section>

   Reference: docs/public/artifact-links-styles.html.
   ═══════════════════════════════════════════════════════════════════════ */

.ds-artifact-links {
  background: #fff;
  border: 1px solid var(--arxiv-border-light);
  border-radius: 6px;
  font-family: var(--arxiv-font-sans);
  overflow: hidden;
}

.ds-artifact-links-title {
  margin: 0;
  padding: 11px 16px;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--arxiv-ink);
  line-height: 1.3;
  border-bottom: 1px solid var(--arxiv-border-light);
}

.ds-artifact-links-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.ds-artifact-links-list > li {
  border-bottom: 1px solid var(--arxiv-border-light);
}

.ds-artifact-links-list > li:last-child {
  border-bottom: none;
}

.ds-artifact-links-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  color: var(--arxiv-ink);
  text-decoration: none;
  font-size: 0.8125rem;
  line-height: 1.4;
  transition: background 0.12s;
}

.ds-artifact-links-row:visited {
  color: var(--arxiv-ink);
}

.ds-artifact-links-row:hover {
  background: var(--arxiv-active-bg);
}

.ds-artifact-links-row:hover .ds-artifact-links-ext {
  stroke: var(--arxiv-grey);
}

.ds-artifact-links-row:focus-visible {
  outline: 3px solid var(--arxiv-focus-ring);
  outline-offset: -2px;
}

.ds-artifact-links-label {
  flex: 1;
  min-width: 0;
  font-weight: 500;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-artifact-links-dest {
  flex-shrink: 0;
  font-family: var(--arxiv-font-condensed);
  font-size: 0.75rem;
  color: var(--arxiv-grey);
  letter-spacing: 0.02em;
}

.ds-artifact-links-ext {
  flex-shrink: 0;
  width: 13px;
  height: 13px;
  stroke: var(--arxiv-grey-ui);
  fill: none;
}

/* Overflow disclosure — mirrors .ds-acc conventions (no-JS, +/− glyph). */
.ds-artifact-links-more {
  border-top: 1px solid var(--arxiv-border-light);
}

.ds-artifact-links-more > summary {
  display: flex;
  align-items: center;
  list-style: none;
  cursor: pointer;
  padding: 9px 16px;
  font-family: var(--arxiv-font-sans);
  font-size: 0.8125rem;
  color: var(--arxiv-link-blue);
  transition: background 0.12s, color 0.12s;
}

.ds-artifact-links-more > summary::-webkit-details-marker { display: none; }
.ds-artifact-links-more > summary::marker { content: ""; }

.ds-artifact-links-more > summary::after {
  content: "+";
  content: "+" / "";  /* alt-text: the glyph is decorative — <details> announces state */
  margin-left: auto;
  font-weight: 400;
  color: var(--arxiv-grey);
  font-size: 1.1rem;
  line-height: 1;
}

.ds-artifact-links-more[open] > summary {
  border-bottom: 1px solid var(--arxiv-border-light);
}

.ds-artifact-links-more[open] > summary::after {
  content: "−";
  content: "−" / "";
}

.ds-artifact-links-more > summary:hover {
  background: var(--arxiv-active-bg);
  color: var(--arxiv-link-hover);
}

.ds-artifact-links-more > summary:focus-visible {
  outline: 3px solid var(--arxiv-focus-ring);
  outline-offset: -2px;
}

@media (prefers-reduced-motion: reduce) {
  .ds-artifact-links-row,
  .ds-artifact-links-more > summary { transition: none; }
}

@media (forced-colors: active) {
  .ds-artifact-links { border-color: ButtonBorder; }
  .ds-artifact-links-ext { stroke: ButtonText; }
  .ds-artifact-links-row:hover { background: Highlight; color: HighlightText; }
  .ds-artifact-links-row:hover .ds-artifact-links-ext { stroke: HighlightText; }
}


